import aiohttp
import json
import os
import ssl
from .models import RequestType
from .exceptions import RpcError, NotSupportedRequestType

REQUEST_TIMEOUT = 60 * 8


def get_default_cert_bundle():
    certbundlefile = os.path.join(os.path.dirname(__file__), "RootCertsBundle.crt")
    return certbundlefile


class _ResponseWrapper:
    """Minimal wrapper to mimic Response interface used downstream."""
    def __init__(self, status, headers, body: bytes):
        self.status_code = status
        self.headers = headers
        self._body = body

    def json(self):
        return json.loads(self._body.decode())

    @property
    def text(self):
        return self._body.decode()


class AioRpc:
    """
    Dynamic Async Rpc to establish JSON-RPC connection over http or https transport.

    If you provide transport type directly than it takes precedence over indirect transport selection.
    If transport type is not provided then it is selected indirectly:

    - if certificates bundle is provided then we spek over https
    - if provided port is 443 then we speak over https
    - else we use http

    If port is not provided then we use default port numbers (http: 80, https: 443)

    Whenever client calls method not visible in AioRpc class like::
      await aiorpc.attach(ue_id=id)

    then it is on-the-fly converted to `await aiorpc.call(method="attach", ue_id=id)`
    and then passed over to remote side as JSON-RPC 2.0
    So, `await aiorpc.attach()` assumes existence of same named method exposed by Rpc server.
    """

    def __init__(self, hostname, port=None, transport_type=None, certbundle=None, *, client_timeout=REQUEST_TIMEOUT):
        """
        Establish JSON-RPC connection over http or https transport.

        When https is selected (anyway) but no certificate is given
        then we use development time certificates (self-signed) - double check if that matches with UE-proxy server.
        (UE-proxy server uses dev-time certs when started with --dev_https flag)
        """
        if transport_type is None:
            if certbundle or (port == 443):
                transport_type = "https"
            else:
                transport_type = "http"
        assert transport_type in ["http", "https"]

        if port is None:
            port = 80 if transport_type == "http" else 443

        self.hostname = hostname
        self.port = port
        self.transport_type = transport_type
        self.remote_url = f"{transport_type}://{hostname}:{port}"
        self.remote_rpc_endpoint = "/api/v1/jsonrpc"
        if certbundle:
            if not os.path.isfile(certbundle):
                raise TypeError(f"certbundle={certbundle} is not file or doesn't exist")
        else:
            certbundle = get_default_cert_bundle()
        self.certbundle = certbundle
        self._req_id = 0
        self._session: aiohttp.ClientSession | None = None
        self._client_timeout = client_timeout
        self._ssl_ctx = self._build_ssl_ctx()

    def _build_ssl_ctx(self):
        if self.transport_type == "https":
            ctx = ssl.create_default_context(cafile=self.certbundle)
            return ctx
        return None  # No SSL verification for http

    @staticmethod
    async def close():
        """
        Close underlying HTTP session.

        After that instance is not usable anymore (in `__aexit__` called automatically).

        :return: None
        """
        # No persistent session to be closed
        return None

    async def __aenter__(self):
        return self

    async def _send_post_request(self, url, data, timeout):
        timeout_obj = aiohttp.ClientTimeout(total=timeout)
        async with aiohttp.ClientSession(timeout=timeout_obj) as session:
            async with session.post(url, json=data, ssl=self._ssl_ctx, timeout=timeout) as resp:
                resp.raise_for_status()
                return await resp.json()

    @staticmethod
    def _validate_response(request, response, remote):
        if 'result' not in response:
            err = response['error'] if 'error' in response else response
            raise RpcError(request=request, response=err, remote=remote)
        return response['result']

    def _next_msg_id(self):
        self._req_id = (self._req_id + 1) % 60000
        return self._req_id

    async def notify(self, method, **kwargs):
        """
        Notify with POST request.

        No response expected for notification.
        In "id" field there is no value - see: https://www.jsonrpc.org/specification#notification

        :param method: method name
        :param kwargs: method parameters
        :return: None
        """
        rpc_payload = {"jsonrpc": "2.0",
                       "method": method,
                       "params": kwargs}
        await self._send_post_request(url=f"{self.remote_url}{self.remote_rpc_endpoint}",
                                      data=rpc_payload,
                                      timeout=REQUEST_TIMEOUT)
        return None  # No response expected for notification

    async def _prepare_and_send_post_request(self, method, params, timeout):
        rpc_payload = {"jsonrpc": "2.0",
                       "id": self._next_msg_id(),  # method and self taken from stack
                       "method": method,
                       "params": params}
        response = await self._send_post_request(url=f"{self.remote_url}{self.remote_rpc_endpoint}/{method}",
                                                 data=rpc_payload,
                                                 timeout=timeout)
        method_call = "{}({})".format(method, ", ".join([f"{par}={val}" for par, val in params.items()]))
        return self._validate_response(request=method_call,
                                       response=response,
                                       remote=f"{self.remote_url}{self.remote_rpc_endpoint}")

    async def _send_get_request(self, method, params, timeout=REQUEST_TIMEOUT):
        url = f"{self.remote_url}{self.remote_rpc_endpoint}/{method}"
        timeout_obj = aiohttp.ClientTimeout(total=timeout)
        async with aiohttp.ClientSession(timeout=timeout_obj) as session:
            async with session.get(url, params=params, ssl=self._ssl_ctx, timeout=timeout) as resp:
                resp.raise_for_status()
                return _ResponseWrapper(resp.status, resp.headers, await resp.read())

    def __getattr__(self, item):
        """
        Dynamic method resolution of RPC.

        Whenever client calls method not visible in AioRpc class like:
          `await aiorpc.attach(ue_id=id)`

        then it is on-the-fly converted to `await rpc.call(method="attach", ue_id=id)`
        and then passed over to remote side as JSON-RPC 2.0
        So, `await aiorpc.attach()` assumes existence of same named method exposed by Rpc server.
        """
        method = item

        async def _call_remote_method(*args, **kwargs):
            if args:
                args_str = ", ".join(map(str, args))
                raise TypeError(f"Incorrect RPC call '{method}({args_str})' - only keyword arguments allowed")
            request_type = kwargs.pop("request_type", "post")
            request_timeout = kwargs.pop("request_timeout", REQUEST_TIMEOUT)
            params = kwargs if kwargs else {}
            if request_type == RequestType.post:
                return await self._prepare_and_send_post_request(method, params, request_timeout)
            elif request_type == RequestType.get:
                return await self._send_get_request(method, params, request_timeout)
            else:
                raise NotSupportedRequestType(request_type)

        return _call_remote_method
